package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.RegisterBookUseCase;
import com.example.lending.application.port.in.RegisterBookUseCase.RegisterBookCommand;
import com.example.lending.application.port.in.SearchBooksUseCase;
import com.example.lending.application.port.in.SearchBooksUseCase.SearchBooksQuery;
import com.example.lending.domain.Book;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@RestController
@RequestMapping("/books")
public class BookController {

    private final RegisterBookUseCase registerBookUseCase;
    private final SearchBooksUseCase searchBooksUseCase;

    public BookController(RegisterBookUseCase registerBookUseCase, SearchBooksUseCase searchBooksUseCase) {
        this.registerBookUseCase = registerBookUseCase;
        this.searchBooksUseCase = searchBooksUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public BookResponse registerBook(@RequestBody RegisterBookRequest request) {
        Book book = registerBookUseCase.registerBook(new RegisterBookCommand(request.title()));
        return BookResponse.from(book);
    }

    // 제목에 검색어가 포함된 책을 대소문자 구분 없이 찾는다. 맞는 책이 없으면 빈 목록이다
    @GetMapping
    public List<BookResponse> searchBooks(@RequestParam String title) {
        return searchBooksUseCase.searchBooks(new SearchBooksQuery(title)).stream()
                .map(BookResponse::from)
                .toList();
    }
}
package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.LoanBookUseCase;
import com.example.lending.application.port.in.LoanBookUseCase.LoanBookCommand;
import com.example.lending.application.port.in.ReturnBookUseCase;
import com.example.lending.application.port.in.ReturnBookUseCase.ReturnBookCommand;
import com.example.lending.domain.Loan;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.time.LocalDate;
import java.util.UUID;

@RestController
@RequestMapping("/loans")
public class LoanController {

    private final LoanBookUseCase loanBookUseCase;
    private final ReturnBookUseCase returnBookUseCase;

    public LoanController(LoanBookUseCase loanBookUseCase, ReturnBookUseCase returnBookUseCase) {
        this.loanBookUseCase = loanBookUseCase;
        this.returnBookUseCase = returnBookUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public LoanResponse loanBook(@RequestBody LoanRequest request) {
        Loan loan = loanBookUseCase.loanBook(new LoanBookCommand(request.bookId(), request.memberId(), request.loanedAt()));
        return LoanResponse.from(loan);
    }

    @PostMapping("/{loanId}/return")
    public ReturnLoanResponse returnBook(@PathVariable UUID loanId,
                                         @RequestBody(required = false) ReturnLoanRequest request) {
        LocalDate returnedAt = request == null ? null : request.returnedAt();
        Loan loan = returnBookUseCase.returnBook(new ReturnBookCommand(loanId, returnedAt));
        return ReturnLoanResponse.from(loan);
    }
}
package com.example.lending.adapter.in.web;

import com.example.lending.domain.AlreadyReturnedException;
import com.example.lending.domain.BookAlreadyOnLoanException;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.LoanLimitExceededException;
import com.example.lending.domain.LoanNotFoundException;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(LoanLimitExceededException.class)
    public ResponseEntity<ErrorResponse> handleLoanLimitExceeded(LoanLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("LOAN_LIMIT_EXCEEDED"));
    }

    @ExceptionHandler(AlreadyReturnedException.class)
    public ResponseEntity<ErrorResponse> handleAlreadyReturned(AlreadyReturnedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("ALREADY_RETURNED"));
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    public ProblemDetail handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}
