                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        LocalDate returnedAt = Objects.requireNonNullElseGet(command.returnedAt(), LocalDate::now);
        book.returnLoan(loan, returnedAt);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        return loan;
