import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookDiscardIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void discarding_an_available_book_returns_discarded_status() throws Exception {
        String bookId = registerBook("Damaged Book");

        mockMvc.perform(post("/books/" + bookId + "/discard"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(bookId))
                .andExpect(jsonPath("$.title").value("Damaged Book"))
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarded_book_cannot_be_loaned() throws Exception {
        String memberId = registerMember("이서연");
        String bookId = registerBook("Lost Book");
        mockMvc.perform(post("/books/" + bookId + "/discard")).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void book_on_loan_cannot_be_discarded() throws Exception {
        String memberId = registerMember("최도윤");
        String bookId = registerBook("Borrowed Book");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated());

        mockMvc.perform(post("/books/" + bookId + "/discard"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_ON_LOAN"));
    }

    @Test
    void book_returned_after_loan_can_be_discarded() throws Exception {
        String memberId = registerMember("정하준");
        String bookId = registerBook("Returned Book");
        String loanId = loanBook(bookId, memberId);
        mockMvc.perform(post("/loans/" + loanId + "/return"))
                .andExpect(status().isOk());

        mockMvc.perform(post("/books/" + bookId + "/discard"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_twice_keeps_discarded_status() throws Exception {
        String bookId = registerBook("Twice Discarded");
        mockMvc.perform(post("/books/" + bookId + "/discard")).andExpect(status().isOk());

        mockMvc.perform(post("/books/" + bookId + "/discard"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_unknown_book_returns_404() throws Exception {
        mockMvc.perform(post("/books/" + UUID.randomUUID() + "/discard"))
                .andExpect(status().isNotFound());
    }

    @Test
    void discarded_book_is_still_found_by_search() throws Exception {
        String marker = "Disc" + UUID.randomUUID().toString().substring(0, 8);
        String bookId = registerBook("Searchable " + marker);
        mockMvc.perform(post("/books/" + bookId + "/discard")).andExpect(status().isOk());

        mockMvc.perform(get("/books").param("title", marker))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].status").value("DISCARDED"));
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }

    record LoanBody(String bookId, String memberId) {
    }
}

